package psparse

import (
	"bufio"
	"encoding/base64"
	"encoding/json"
	"os"
	"os/exec"
	"testing"
)

// The nested-script gate compares ExtractNestedScripts (kind, static, decoded
// text) against a committed golden of the pwsh 7.7 reference extraction, with
// no PowerShell at gate time. The golden is generated by a pwsh oracle
// (nestedOracleScript) that locates the same -Command / -EncodedCommand / cmd
// /c payload from the pwsh AST element values and decodes -EncodedCommand with
// the .NET UTF-16LE decoder. It enforces the N2 safety invariant: a nested
// script with no text is never Static=true.

const nestedGoldenFile = "testdata/nested_golden.jsonl"

// nestedCorpus is the security-relevant nested-script corpus (hosts, cmd /c,
// Invoke-Expression, [scriptblock]::Create, --% payloads, dynamic payloads).
func nestedCorpus() []string {
	raw := []string{
		`powershell -Command "Remove-Item C:\x"`, `powershell -c Remove-Item C:\x`,
		`pwsh -c "Remove-Item $env:TEMP"`, `powershell -NoProfile -Command Remove-Item C:\x`,
		`powershell -enc ZQBjAGgAbwAgAGgAaQA=`, `powershell -EncodedCommand ZQBjAGgAbwAgAGgAaQA=`,
		`powershell -NoP -NonI -W Hidden -Exec Bypass -Enc ZQBjAGgAbwAgAGgAaQA=`,
		`powershell -ExecutionPolicy Bypass -File x.ps1`,
		`C:\Windows\System32\WindowsPowerShell\v1.0\powershell.exe -EncodedCommand ZQBjAGgAbwAgAGgAaQA=`,
		`cmd /c del C:\x`, `cmd /c "del C:\x"`, `cmd.exe /c del C:\x & del C:\y`,
		`cmd /c --% del %TEMP%\x`,
		// (powershell -Command --% <text> is non-static since review 8 R8-1: the caller
		// expands %NAME% in the tail, which the AST oracle does not model; see rev7_test.go.)
		`cmd /k dir`, `& $env:ComSpec /c del C:\x`,
		`powershell -Command $payload`,
		// review 3 R3: -Version/-v takes a value (the PS 2.0 downgrade evasion)
		`powershell -Version 2 -c Remove-Item C:\x`, `powershell -v 2 -enc ZQBjAGgAbwAgAGgAaQA=`,
		`powershell -Version 2.0 -Command "Remove-Item C:\y"`,
		`powershell -Version 5.1 -NoProfile -EncodedCommand ZQBjAGgAbwAgAGgAaQA=`,
		`powershell -version 2 -nop -w hidden -c "Remove-Item C:\x"`,
		// (the -Version positional-script and Start-Process -ArgumentList shapes
		// are fixed and dump-verified too, but this nested oracle does not model
		// positional/Start-Process extraction -- see R12 -- so they are not gated.)
		// review 4 R4-4: -EncodedArguments is a value flag, never the payload
		`powershell -EncodedArguments UABMAEEAQwBFAEgATwBMAEQA -EncodedCommand ZQBjAGgAbwAgAGgAaQA=`,
		`powershell -encodeda UABMAEEAQwBFAEgATwBMAEQA -c Remove-Item C:\x`,
		// tested host-call shapes (host_shapes.go): switches, options, multi-word and encoded
		`pwsh -nop -noni -c Write-Output a`, `powershell -NoLogo -NoProfile -NonInteractive -Command "Get-Date"`,
		`pwsh -w hidden -ep Bypass -c Get-Date`, `powershell -c Write-Output a b`,
		`pwsh -e ZQBjAGgAbwAgAGgAaQA=`, `pwsh -wd C:\ -c Get-Date`, `pwsh -if text -of text -c Get-Date`,
		`cmd /q /d /c ver`, `cmd /e:on /v:off /c ver`, `cmd /K ver`, `cmd /s /r ver`, `cmd /a /u /c ver`,
		// outside the tested shapes: the oracle resolves a script, psparse is NotStatic (nestedUnderStatic)
		`cmd foo /c ver`, `pwsh -nop -foo -c Get-Date`, `pwsh -sta -version 2 -c Get-Date`,
	}
	seen := map[string]bool{}
	var out []string
	for _, s := range raw {
		if !seen[s] {
			seen[s] = true
			out = append(out, s)
		}
	}
	return out
}

// nestedUnderStatic are corpus lines outside the tested host-call shapes
// (host_shapes.go): the AST oracle resolves a script text, psparse reports
// NotStatic. The gate still fails if psparse is Static and disagrees.
var nestedUnderStatic = map[string]bool{
	`cmd /c "del C:\x"`:                                                                          true, // a payload word with a quote or whitespace (review 9 R9-2)
	`pwsh -wd C:\ -c Get-Date`:                                                                   true, // -wd moves the child's working directory (review 9 R9-1)
	`cmd /c --% del %TEMP%\x`:                                                                    true,
	`powershell -Version 2 -c Remove-Item C:\x`:                                                  true,
	`powershell -v 2 -enc ZQBjAGgAbwAgAGgAaQA=`:                                                  true,
	`powershell -Version 2.0 -Command "Remove-Item C:\y"`:                                        true,
	`powershell -Version 5.1 -NoProfile -EncodedCommand ZQBjAGgAbwAgAGgAaQA=`:                    true,
	`powershell -version 2 -nop -w hidden -c "Remove-Item C:\x"`:                                 true,
	`powershell -EncodedArguments UABMAEEAQwBFAEgATwBMAEQA -EncodedCommand ZQBjAGgAbwAgAGgAaQA=`: true,
	`powershell -encodeda UABMAEEAQwBFAEgATwBMAEQA -c Remove-Item C:\x`:                          true,
	`cmd foo /c ver`:                   true,
	`pwsh -nop -foo -c Get-Date`:       true,
	`pwsh -sta -version 2 -c Get-Date`: true,
}

type nestedGoldLine struct {
	I  int              `json:"i"`
	NS []nestedGoldItem `json:"ns"`
}
type nestedGoldItem struct {
	Kind   string `json:"kind"`
	Text   string `json:"text"`
	Static bool   `json:"static"`
}

func mineNested(s string) []nestedGoldItem {
	sc, _ := Parse(s, Options{})
	var out []nestedGoldItem
	for _, n := range ExtractNestedScripts(sc) {
		out = append(out, nestedGoldItem{Kind: n.Kind, Text: n.Text, Static: n.Static})
	}
	return out
}

// TestNestedGolden is the CI gate for nested-script extraction (no pwsh).
func TestNestedGolden(t *testing.T) {
	f, err := os.Open(nestedGoldenFile)
	if err != nil {
		t.Fatalf("golden %s missing (regenerate: PSPARSE_GOLDEN_REGEN=1 PSPARSE_ORACLE=<pwsh> go test -run TestGenNestedGolden): %v", nestedGoldenFile, err)
	}
	golden := map[int][]nestedGoldItem{}
	seenErr := false
	osc := bufio.NewScanner(f)
	osc.Buffer(make([]byte, 1<<20), 1<<24)
	for osc.Scan() {
		var gl nestedGoldLine
		if json.Unmarshal(osc.Bytes(), &gl) == nil {
			golden[gl.I] = gl.NS
			seenErr = true
		}
	}
	f.Close()
	if !seenErr {
		t.Fatalf("golden %s empty", nestedGoldenFile)
	}
	corpus := nestedCorpus()
	for i, s := range corpus {
		mine := mineNested(s)
		// invariant: a static nested script must have non-empty text (N2).
		for _, n := range mine {
			if n.Static && n.Text == "" {
				t.Errorf("nested #%d %q: Static with empty text (must be dynamic)", i, s)
			}
		}
		want, ok := golden[i]
		if !ok {
			t.Errorf("nested #%d %q: no golden entry", i, s)
			continue
		}
		if nestedUnderStatic[s] && len(mine) == len(want) {
			// outside the tested host-call shapes: psparse is NotStatic where the
			// AST oracle resolves a script. Never the other way round.
			ok := true
			for k := range mine {
				if mine[k].Static && (!want[k].Static || mine[k].Text != want[k].Text) {
					ok = false
				}
			}
			if ok {
				continue
			}
		}
		if !sameNested(mine, want) {
			t.Errorf("nested #%d %q:\n mine=%v\n want=%v", i, s, mine, want)
		}
	}
}

func sameNested(a, b []nestedGoldItem) bool {
	if len(a) != len(b) {
		return false
	}
	for i := range a {
		if a[i].Kind != b[i].Kind || a[i].Static != b[i].Static || (a[i].Static && a[i].Text != b[i].Text) {
			return false
		}
	}
	return true
}

// TestGenNestedGolden regenerates the nested golden from the pwsh oracle.
func TestGenNestedGolden(t *testing.T) {
	if os.Getenv("PSPARSE_GOLDEN_REGEN") != "1" {
		t.Skip("set PSPARSE_GOLDEN_REGEN=1 and PSPARSE_ORACLE to regenerate")
	}
	pwsh := os.Getenv("PSPARSE_ORACLE")
	if pwsh == "" {
		t.Fatal("PSPARSE_ORACLE required")
	}
	corpus := nestedCorpus()
	in, _ := os.CreateTemp("", "nested-in-*.b64")
	defer os.Remove(in.Name())
	for _, s := range corpus {
		in.WriteString(base64.StdEncoding.EncodeToString([]byte(s)) + "\n")
	}
	in.Close()
	ps1, _ := os.CreateTemp("", "nested-oracle-*.ps1")
	defer os.Remove(ps1.Name())
	ps1.WriteString(nestedOracleScript)
	ps1.Close()
	out, err := exec.Command(pwsh, "-NoProfile", "-NonInteractive", "-File", ps1.Name(), in.Name()).Output()
	if err != nil {
		t.Fatalf("oracle: %v %s", err, tailStderr(err))
	}
	if err := os.MkdirAll("testdata", 0o755); err != nil {
		t.Fatal(err)
	}
	if err := os.WriteFile(nestedGoldenFile, out, 0o644); err != nil {
		t.Fatal(err)
	}
	t.Logf("wrote %s (%d lines)", nestedGoldenFile, len(corpus))
}

// nestedOracleScript extracts, for each input line, the nested payload the way
// pwsh resolves it. It models only the powershell/pwsh host (-Command, a
// decoded -EncodedCommand, a positional/-Version script) and the cmd /c tail,
// which is what the gated nestedCorpus covers. Invoke-Expression,
// [scriptblock]::Create and Start-Process -ArgumentList are NOT modelled here
// (review 4 R12); their extraction is covered by direct unit tests
// (TestNestedIEXList, nested_scripts_test.go) instead of this golden.
const nestedOracleScript = `
param([string]$InFile)
$ErrorActionPreference = 'Stop'
function Base($n) { $n = ($n -replace '\\','/'); $n = $n.Substring($n.LastIndexOf('/')+1); $n = $n.ToLower(); if ($n.EndsWith('.exe')) { $n = $n.Substring(0,$n.Length-4) }; return $n }
function ElemVal($e) {
  $tn = $e.GetType().Name
  if ($tn -eq 'StringConstantExpressionAst' -or $tn -eq 'ConstantExpressionAst') { return @{ v=[string]$e.Value; ok=$true } }
  return @{ v=''; ok=$false }
}
function DecodeEnc($b64) {
  try { $bytes=[Convert]::FromBase64String($b64); return @{ v=[System.Text.Encoding]::Unicode.GetString($bytes); ok=$true } } catch { return @{ v=''; ok=$false } }
}
$lines=[System.IO.File]::ReadAllLines($InFile); $i=-1
foreach($line in $lines){
  $i++
  $text=[System.Text.Encoding]::UTF8.GetString([System.Convert]::FromBase64String($line))
  $ast=[System.Management.Automation.Language.Parser]::ParseInput($text,[ref]$null,[ref]$null)
  $cmds=$ast.FindAll({param($n) $n -is [System.Management.Automation.Language.CommandAst]},$true)
  $ns=New-Object System.Collections.ArrayList
  foreach($c in $cmds){
    $els=$c.CommandElements; if($els.Count -eq 0){continue}
    $name=''; $n0=$els[0]; if($n0.GetType().Name -match 'String|Constant'){$name=[string]$n0.Value}
    $b=Base $name
    if($b -eq 'powershell' -or $b -eq 'pwsh'){
      $k=1; $done=$false
      while($k -lt $els.Count -and -not $done){
        $el=$els[$k]
        if($el.GetType().Name -eq 'CommandParameterAst'){
          $pn=([string]$el.ParameterName).ToLower()
          if($pn -eq 'c' -or 'command'.StartsWith($pn)){
            $parts=@(); $allok=$true
            for($j=$k+1;$j -lt $els.Count;$j++){ if($els[$j].GetType().Name -eq 'CommandParameterAst'){ $v2=@{v=('-'+$els[$j].ParameterName);ok=$true} } else { $v2=ElemVal $els[$j] }; if(-not $v2.ok){$allok=$false;break}; if($v2.v -ne '--%'){ $parts += $v2.v } }
            $txt = ($parts -join ' ')
            [void]$ns.Add([ordered]@{kind='powershell-command'; text=$txt; static=($allok -and $txt -ne '')}); $done=$true
          } elseif('encodedcommand'.StartsWith($pn) -and $pn[0] -eq 'e'){
            $v2= if($k+1 -lt $els.Count){ElemVal $els[$k+1]}else{@{v='';ok=$false}}
            if($v2.ok){ $d=DecodeEnc $v2.v; [void]$ns.Add([ordered]@{kind='encodedcommand'; text=$d.v; static=($d.ok -and $d.v -ne '')}) } else { [void]$ns.Add([ordered]@{kind='encodedcommand'; text=''; static=$false}) }
            $done=$true
          } elseif($pn -eq 'f' -or 'file'.StartsWith($pn)){ $done=$true }
          else { $k++ }
        } else { $k++ }
      }
    } elseif($b -eq 'cmd'){
      for($k=1;$k -lt $els.Count;$k++){ $v=ElemVal $els[$k]; if($v.ok -and ($v.v.ToLower() -eq '/c' -or $v.v.ToLower() -eq '/k' -or $v.v.ToLower() -eq '/r')){ $parts=@(); $allok=$true; for($j=$k+1;$j -lt $els.Count;$j++){ $v2=ElemVal $els[$j]; if(-not $v2.ok){$allok=$false;break}; if($v2.v -ne '--%'){ $parts += $v2.v } }; $txt=($parts -join ' '); [void]$ns.Add([ordered]@{kind='cmd-c'; text=$txt; static=($allok -and $txt -ne '')}); break } }
    }
  }
  Write-Output ([ordered]@{ i=$i; ns=$ns } | ConvertTo-Json -Compress -Depth 20)
}
`
